from odoo import api, models
from odoo.exceptions import ValidationError


class XLibLoan(models.Model):
    _inherit = 'x_lib_loan'

    @api.constrains('x_loan_date', 'x_due_date', 'x_return_date')
    def _check_loan_dates(self):
        for record in self:
            if record.x_loan_date and record.x_due_date and record.x_due_date < record.x_loan_date:
                raise ValidationError('Due date must be on or after loan date.')
            if record.x_return_date and record.x_loan_date and record.x_return_date < record.x_loan_date:
                raise ValidationError('Return date must be on or after loan date.')

from odoo import api, fields, models


class XLibLoanCompute(models.Model):
    _inherit = 'x_lib_loan'

    @api.depends('x_due_date', 'x_returned', 'x_book_id', 'x_book_id.x_fine_rate')
    def _compute_overdue_fine(self):
        today = fields.Date.context_today(self)
        for record in self:
            if record.x_returned or not record.x_due_date:
                record.x_days_overdue = 0
                record.x_fine_amount = 0.0
                continue
            days = max((today - record.x_due_date).days, 0)
            rate = (record.x_book_id.x_fine_rate if record.x_book_id else 0.0) or 0.0
            record.x_days_overdue = days
            record.x_fine_amount = float(days) * float(rate)

from odoo import api, fields, models


class XLibLoanCron(models.Model):
    _inherit = 'x_lib_loan'

    @api.model
    def cron_send_overdue_reminders(self):
        today = fields.Date.context_today(self)
        overdue = self.search([
            ('x_returned', '=', False),
            ('x_due_date', '<', today),
        ])
        tpl = self.env.ref(
            'library_management.mail_template_loan_overdue', raise_if_not_found=False
        )
        if not tpl:
            return True
        for loan in overdue:
            member = loan.x_member_id
            if member and member.email:
                tpl.send_mail(loan.id, force_send=False)
        return True
